export function WalletAdminServiceControllerMethods() {
  return function (constructor: Function) {
    const grpcMethods: string[] = [
      "getHolderWallet",
      "listHolderStatement",
      "listWalletPayouts",
      "getLedgerOverview",
      "creditPrepaidWallet",
      "listManualCreditRequests",
      "approveManualCredit",
    ];
    for (const method of grpcMethods) {
      const descriptor: any = Reflect.getOwnPropertyDescriptor(constructor.prototype, method);
      GrpcMethod("WalletAdminService", method)(constructor.prototype[method], method, descriptor);
      Object.defineProperty(constructor.prototype, method, descriptor);
    }
    const grpcStreamMethods: string[] = [];
    for (const method of grpcStreamMethods) {
      const descriptor: any = Reflect.getOwnPropertyDescriptor(constructor.prototype, method);
      GrpcStreamMethod("WalletAdminService", method)(constructor.prototype[method], method, descriptor);
      Object.defineProperty(constructor.prototype, method, descriptor);
    }
  };
}

